mapper.select:
SELECT U.id, U.tenant_id, U.pin, U.nickname, U.status, U.last_login_at, U.gender, U.avatar_url, U.must_change_password, U.del_flag, U.created_at, U.created_by, U.updated_at, U.updated_by, U.phone_no_masked, U.phone_no_blind_index, U.phone_no_tail_blind_index, U.email_masked, U.email_blind_index FROM sys_user U WHERE NOT EXISTS ( SELECT 1 FROM sys_user_dept_relation UDR WHERE UDR.user_id = U.id )
AND U.phone_no_tail_blind_index = #{phoneTailBlindIndex}
AND U.id NOT IN
#{item}
ORDER BY U.id DESC
